/// assert!(!contains_key(&env, c"FOO=1", b'='));
/// ```
///
/// Replaces `fn::git_strlist_contains_key`
#[doc(alias = "git_strlist_contains_key")]
#[must_use]
pub fn contains_key<S: AsRef<CStr>>(strings: &[S], key: &CStr, delimiter: u8) -> bool {
    let key = key.to_bytes();
