/// borrowing a pointer cannot lose the element type or the free strategy.
#[repr(transparent)]
pub struct StackRef<'a, T, S>(CBorrowedPtr<'a, Stack<T, S>>);
impl<T, S> Clone for StackRef<'_, T, S> {
    fn clone(&self) -> Self {
        *self
