}
impl<T, S> Copy for StackRef<'_, T, S> {}

/// The hand-written exclusive handle.
#[repr(transparent)]
pub struct StackMut<'a, T, S>(StackRef<'a, T, S>, PhantomData<&'a mut Stack<T, S>>);

