// A shared handle copies like `&T`; `#[derive]` would add a spurious `T: Copy`.
impl<T> Copy for CBorrowedPtr<'_, T> {}

impl<'a, T> CBorrowedPtr<'a, T> {
    /// Wrap a non-null pointer to the wrapper type.
    ///
    /// # Safety
    ///
    /// `p` must address a live, initialised object that outlives `'a`.
    #[inline]
    pub const unsafe fn new(p: NonNull<T>) -> Self {
        Self {
            ptr: p,
            _borrow: PhantomData,
        }
    }

    /// The wrapper pointer this handle borrows.
    #[inline]
    #[must_use]
    pub const fn as_non_null(self) -> NonNull<T> {
        self.ptr
    }
}

/// Build `T`'s shared handle from a pointer to it.
///
/// The one place a handle is made generically: [`CCell`]'s contract makes
/// `T::Ref<'a>` `#[repr(transparent)]` over `CBorrowedPtr<'a, T>`, so the
/// conversion is a layout-preserving copy. Reached from outside only through
    /// `*const C` and for field reads through `addr_of!`. A C routine that
    /// writes the object under a lock it takes itself, which
    /// [`CCell::ref_from_ptr`]'s contract allows, may take it only for a type
    /// Rust never holds by value: a handle built from `&self`, as a layout
    /// type's own `as_ref` builds one, carries a pointer that may only be
    /// read through.
    #[inline]
    #[must_use]
    fn as_ptr(&self) -> *const <Self::Cell as CCell>::C {
        crate::refs::ref_handle_ptr::<Self::Cell>(self)
            .as_ptr()
            .cast_const()
            .cast()
    }

    /// Type-erased `*const c_void`, for read-only `void *` shims.
    #[inline]
    #[must_use]
    fn as_void_ptr(&self) -> *const c_void {
        self.as_ptr().cast()
    }
