    assert_eq!(strnlen(b"\0"), 0);
    assert_eq!(strnlen(b"\0abc"), 0);
    assert_eq!(strnlen(b"ab\0cd"), 2);
    assert_eq!(strnlen(b"abc\0"), 3);
    assert_eq!(strnlen(b"a\0\0b\0"), 1);
    assert_eq!(strnlen(&[0; 16]), 0);
}

