#[test]
fn without_a_nul_the_bound_is_the_length() {
    assert_eq!(strnlen(b"a"), 1);
    assert_eq!(strnlen(b"abcdef"), 6);
    assert_eq!(strnlen(&b"abc\0"[..3]), 3);
    assert_eq!(strnlen(&b"abcdef\0"[..4]), 4);
}

